package dev.livingrealms.minecraft.entity;
import dev.livingrealms.minecraft.LivingRealmsSavedData;import dev.livingrealms.sim.military.*;import dev.livingrealms.sim.util.DeterministicRng;import dev.livingrealms.sim.world.SimPosition;import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.server.MinecraftServer;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.levelgen.Heightmap;
public final class MilitaryUnitMaterializer{private MilitaryUnitMaterializer(){}public static void tick(MinecraftServer server,LivingRealmsSavedData data){ServerLevel level=server.overworld();List<SimPosition> players=level.players().stream().map(p->new SimPosition(p.getX(),p.getZ())).toList();List<MilitaryProjection> desired=MilitaryMaterializationPlanner.plan(data.state().factions(),players,data.state().config().physicalRadiusBlocks(),data.state().config().maxPhysicalMilitaryEntities());Set<String> wanted=new HashSet<>();for(MilitaryProjection p:desired)wanted.add(p.projectionKey());Set<String> seen=new HashSet<>();for(MilitaryUnitEntity e:MilitaryUnitIndex.loaded()){String key=e.armyId()+":"+e.projectionSlot();if(!wanted.contains(key)||!seen.add(key))e.dematerialize();}for(MilitaryProjection p:desired){if(MilitaryUnitIndex.forSlot(p.armyId(),p.slot())!=null)continue;SimPosition pos=position(data.state().seed(),p);int x=(int)Math.floor(pos.x()),z=(int)Math.floor(pos.z());BlockPos probe=new BlockPos(x,level.getSeaLevel(),z);if(!level.hasChunkAt(probe))continue;int y=level.getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,x,z);MilitaryUnitEntity e=ModEntities.MILITARY_UNIT.get().create(level);if(e==null)continue;e.initializeProjection(p.armyId(),p.factionId(),p.slot(),p.unitClass(),p.representedPersonnel());e.moveTo(x+.5,y,z+.5,level.random.nextFloat()*360,0);if(level.noCollision(e))level.addFreshEntity(e);}}private static SimPosition position(long seed,MilitaryProjection p){DeterministicRng r=new DeterministicRng(seed^p.armyId()*0x9E3779B97F4A7C15L^p.slot()*0x94D049BB133111EBL);double rad=r.between(2,22),ang=r.between(0,Math.PI*2);return new SimPosition(p.armyPosition().x()+Math.cos(ang)*rad,p.armyPosition().z()+Math.sin(ang)*rad);}}
